from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Callable, Dict

from .ledger import Ledger, Entry
from .upstream import Upstream, UpstreamError, Usage
from .users import UserDirectory
from .pricing import request_cost, UnknownModel
from decimal import Decimal


@dataclass
class Response:
    status: int
    body: dict
    headers: Dict[str, str] = field(default_factory=dict)


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


class Gateway:
    def __init__(self, directory: UserDirectory, upstream: Upstream, ledger: Ledger,
                 clock: Callable[[], datetime] = _utc_now):
        self.directory = directory
        self.upstream = upstream
        self.ledger = ledger
        self.clock = clock
        self._idempotent_store: Dict[tuple, Response] = {}

    def handle(self, request: dict) -> Response:
        # Extract basic fields
        user_id = request.get("user")
        model = request.get("model")
        # Validate user
        try:
            user = self.directory.get(user_id)
        except KeyError:
            return Response(403, {"error": "unknown_user"})
        # Validate model
        try:
            _ = request_cost(model, Usage(0, 0, 0))
        except UnknownModel:
            return Response(400, {"error": "unknown_model"})
        # Idempotency handling
        request_id = request.get("request_id")
        if request_id is not None:
            key = (user_id, request_id)
            if key in self._idempotent_store:
                stored_resp = self._idempotent_store[key]
                resp_copy = Response(stored_resp.status, stored_resp.body.copy(), dict(stored_resp.headers))
                resp_copy.headers["X-Idempotent-Replay"] = "true"
                return resp_copy
        # Admission control for budgeted users
        budget = self.directory.budget(user_id)
        month_str = self.clock().strftime("%Y-%m")
        worst_usage = Usage(request.get("input_tokens", 0), 0, request.get("max_tokens", 0))
        worst_cost = request_cost(model, worst_usage)
        if budget is not None:
            spent = self.ledger.spent(user_id, month_str)
            if spent + worst_cost > budget:
                remaining = max(budget - spent, Decimal("0"))
                return Response(402, {"error": "budget_exceeded", "remaining": f"{remaining.quantize(Decimal('0.000001'))}"})
        # Provider call with retries
        attempts = 0
        spent = self.ledger.spent(user_id, month_str) if budget is not None else Decimal("0")
        while attempts < 3:
            attempts += 1
            try:
                completion = self.upstream(request)
                usage = completion.usage
                cost = request_cost(model, usage)
                entry = Entry(user_id=user_id, month=month_str, model=model, usage=usage, cost=cost, status="ok")
                self.ledger.record(entry)
                # Prepare response
                body = {
                    "content": completion.content,
                    "usage": {"prompt_tokens": usage.prompt_tokens,
                               "cached_tokens": usage.cached_tokens,
                               "completion_tokens": usage.completion_tokens},
                    "cost_usd": f"{cost.quantize(Decimal('0.000001'))}",
                }
                headers: Dict[str, str] = {}
                if budget is not None:
                    new_spent = spent + cost
                    remaining = max(budget - new_spent, Decimal("0"))
                    headers["X-Budget-Remaining"] = f"{remaining.quantize(Decimal('0.000001'))}"
                    if new_spent >= budget:
                        headers["X-Budget-Warning"] = "100%"
                    elif new_spent >= budget * Decimal("0.8"):
                        headers["X-Budget-Warning"] = "80%"
                resp = Response(200, body, headers)
                if request_id is not None:
                    self._idempotent_store[(user_id, request_id)] = resp
                return resp
            except UpstreamError as e:
                if e.usage is not None:
                    failed_cost = request_cost(model, e.usage)
                    entry = Entry(user_id=user_id, month=month_str, model=model, usage=e.usage, cost=failed_cost, status="failed_attempt")
                    self.ledger.record(entry)
                if not e.retryable:
                    break
        return Response(502, {"error": "upstream_failed", "attempts": attempts})"}

